package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class Icon { private int id; public static Icon createWithResource(String pkg,int id){Icon i=new Icon();i.id=id;return i;} public static Icon createWithResource(android.content.Context c,int id){return createWithResource("",id);} public Drawable loadDrawable(android.content.Context c){return Drawable.fromResource(id);} public int getType(){return 2;} public String getResPackage(){return "";} public android.net.Uri getUri(){return null;} public int getResId(){return id;} }